class GSLFunction:
    def __init__(self, func):
        self.func = func

    def __call__(self, x):
        return func(x)

class CQuadWorkspace:
    pass

@ctypes.restype
def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    workspace = (ctypes.c_double * workspace_size)(0)
    result = np.zeros(4, dtype=np.double)
    gsl_integration_cquad.argtypes = [GSLFunction, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.POINTER(CQuadWorkspace), ctypes.POINTER(result), ctypes.POINTER(workspace_size)]
gsl_integration_cquad.restype = None
    func_obj = GSLFunction(func)
gsl_integration_cquad(ctypes.byref(func_obj), a, b, epsabs, epsrel, workspace, ctypes.byref(result), ctypes.byref(workspace_size))
    return {
        "integrate": result[0],
        "abs_error": result[1],
        "neval": int(result[2])
    }

