hesstri_decomp = gslcblas.gsl_linalg_hesstri_decomp

def perform_hesstri_decomp(A, B, U=None, V=None):
    work = np.zeros(64, dtype=np.double)
    if U is None:
        U = np.zeros((4, 4), dtype=np.double)
    else:
        U = U.astype(np.double)

    if V is None:
        V = np.zeros((4, 4), dtype=np.double)
    else:
        V = V.astype(np.double)

    A_gsl = numpy_to_gsl_matrix(A)
    B_gsl = numpy_to_gsl_matrix(B)
    U_gsl = numpy_to_gsl_matrix(U) if U is not None else c_void_p()
    V_gsl = numpy_to_gsl_matrix(V) if V is not None else c_void_p()

    hesstri_decomp(byref(A_gsl), byref(B_gsl), byref(U_gsl), byref(V_gsl), work_type(work))
    A[:] = np.frombuffer(A_gsl, dtype=np.double).reshape((4, 4))
    B[:] = np.frombuffer(B_gsl, dtype=np.double).reshape((4, 4))
    if U is not None:
        U[:] = np.frombuffer(U_gsl, dtype=np.double).reshape((4, 4))
    if V is not None:
        V[:] = np.frombuffer(V_gsl, dtype=np.double).reshape((4, 4))

    return A, B, U, V

