quantile_get = gsl.gsl_rstat_quantile_get
quantile_free = gsl.gsl_rstat_quantile_free

# Define the GslRstatQuantileWorkspace class
class GslRstatQuantileWorkspace:
    def __init__(self):
        self.workspace = quantile_alloc(0)

    def reset(self):
        quantile_reset(self.workspace, 0)

    def add_value(self, value):
        quantile_add(self.workspace, 1.0, ctypes.c_double(value))

    def get_quantile(self, p):
        return quantile_get(self.workspace, ctypes.c_double(p), ctypes.byref(ctypes.c_double(0)))

    def free(self):
        quantile_free(self.workspace)

# Main function to compute the quantile
def compute_quantile(p, values):
    workspace = GslRstatQuantileWorkspace()
    for value in values:
        workspace.add_value(value)
    workspace.reset()
    return str(workspace.get_quantile(p))

