    cdef double *Y_arr = np.array(Y, dtype=np.double).ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    lib.cblas_daxpy(N, alpha, X_arr, 1, Y_arr, 1)
    return list(np.ctypeslib.as_array(Y_arr, (N,), 'd'))

